// Owner: simulation
//
// Residence hall layouts, generated by matching UCR Housing Services'
// community maps (Aberdeen-Inverness, Lothian, Pentland Hills) to the real
// OpenStreetMap footprints. The maps are schematic (not to scale), so the
// wings come from the footprints (centreline a -> b, a = the inner end, and
// wall-to-wall width w) and the maps say what goes where: hall lounges,
// stairs, elevators, trash chutes, and the ground-floor common rooms.
// Slots: [from, to (fractions of the wing from a), side (L/R of a -> b, or
// F = full width), kind, label, floor (0 = every floor)].
// Areas are rooms outside the wings (lobbies, hubs), as scene-metre quads.
import type { CellKind } from "./floorPlan";

export type Slot = [number, number, "L" | "R" | "F", CellKind, string, number];
export type WingSpec = {
  letter: string;
  a: [number, number];
  b: [number, number];
  /** Wall-to-wall width at a and at b (wings can taper). */
  w: number;
  w2: number;
  /** double: rooms both sides of a corridor; suites: Pentland suites; none: only its slots. */
  style: "double" | "suites" | "none";
  roomW: number;
  hall: number;
  slots: Slot[];
};
export type AreaSpec = { corners: [number, number][]; kind: CellKind; label: string; floor: number };
export type HallLayout = { wings: WingSpec[]; areas: AreaSpec[] };

